public static bool IsMirror(int[] arr)
{
if (arr.Length%2 != 0)
{
return false;
}
else
{
for (int i=0; i<arr.Length; i++)
{
bool mirror = false;
for (int j=0; j<arr.Length; j++)
{
if (arr[i]+arr[j] == 0)
{
mirror = true;
}
}
if (mirror == false)
{
return false;
}
}
return true;
}

public static void ArrangeMirror(int[] arr)
{
int count = 0;
int[] save = new int[arr.Length/2];
for (int i=0; i<arr.Length; i++)
{
if (0+arr[i] > 0)
{
save[count] = arr[i];
count++;
}
}
count = 0;
for (int i=1; i<arr.Length; i+2)
{
arr[i-1] = save[count];
arr[i] = save[-count];
count++;
}
}

